import Foundation

/// The licenses Settings › About › Acknowledgements shows: simplyHermes's own (MIT) and every third-party package a
/// built app contains, with its license text and NOTICE file (board row 132). A released build must ship these.
///
/// The list is generated by `tools/acknowledgements/generate.py` into `acknowledgements.json`; tests check it against
/// `Package.resolved`, `project.yml` and `THIRD_PARTY_NOTICES.md`.
public struct Acknowledgements: Sendable, Equatable, Decodable {
    public struct Entry: Sendable, Equatable, Decodable, Identifiable {
        public var name: String
        public var url: String?
        public var version: String?
        /// SPDX id, such as `MIT` or `Apache-2.0`.
        public var license: String
        public var licenseText: String
        /// The package's NOTICE file, which Apache-2.0 requires a build to carry. Nil when it has none.
        public var notice: String?
        public var id: String { name }
    }

    /// simplyHermes itself.
    public var app: Entry
    /// Third-party packages by identity, such as `swift-nio`.
    public var packages: [String: Entry]
    /// Build-time tools that never ship in the app, with the reason.
    public var buildOnly: [String: String]

    /// The packages in the order the screen lists them: by name, case-insensitive.
    public var sortedPackages: [Entry] {
        packages.values.sorted { $0.name.localizedCaseInsensitiveCompare($1.name) == .orderedAscending }
    }

    /// The bundled list.
    public static func bundled() throws -> Acknowledgements {
        guard let url = Bundle.module.url(forResource: "acknowledgements", withExtension: "json") else {
            throw CocoaError(.fileNoSuchFile)
        }
        return try JSONDecoder().decode(Acknowledgements.self, from: Data(contentsOf: url))
    }
}
